from .executor import Executor
from abc import abstractmethod, ABCMeta
from six import add_metaclass
import os
import re
import logging


@add_metaclass(ABCMeta)
class TtiTrace(object):

    def __init__(self, host_ip, ssh_username, ssh_password,
                 ssh_prompt, ssh_port, stream_path, tracer_path, ip_addr, timeout, log_path, sw_version, cells_sw_type):
        self._executor = Executor(host_ip=host_ip,
                                  ssh_username=ssh_username,
                                  ssh_password=ssh_password,
                                  ssh_port=ssh_port,
                                  ssh_prompt=ssh_prompt,
                                  timeout=timeout)
        self._ensure_ttitracers_are_exist(sw_version)
        self._cells_sw_type = cells_sw_type
        self._stream_path = stream_path or self._get_default_stream_path()
        self._tracer_path = tracer_path or self._get_default_tracer_path()
        self._ensure_ttitracers_are_executable()
        self._log_files = []
        self._is_server_model = False
        self._server_started = False
        self._port = []
        self._log_path = log_path
        self._prepare_log_path()

    @abstractmethod
    def start_tti_stream(self, core, param):
        """Start ttiStream with provided params
        """

    @abstractmethod
    def stop_tti_stream(self, lrc):
        """Stop running ttiStream
        """

    @abstractmethod
    def stop_tti_stream_and_convert_to_text(self, nb, ext, lrc):
        """Stop running ttiStream and convert dat files to txt
        :param nb bool:                 Use NB parsing flag
        :return list:                   List of successfully converted txt file
        """

    @abstractmethod
    def convert_dat_to_text(self, source, destination, nb, ext='txt'):
        """Converts source dat file to readable text file
        :param source string:           Input dat file name
        :param destination string:      Output txt file name
        :param nb bool:                 Use NB parsing flag
        :return string:                 Output txt file or empty string if txt file not created
        """

    @abstractmethod
    def get_tti_dl_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:                TTI DL Node
        """

    @abstractmethod
    def get_tti_ul_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:         TTI UL Node
        """

    @abstractmethod
    def _get_default_stream_path(self):
        pass

    @abstractmethod
    def _get_default_tracer_path(self):
        pass

    def _attach_log_path_to_output(self, output):
        return [self._attach_log_path_if_not_absolute(dat_file) for dat_file in output]

    def _attach_log_path_if_not_absolute(self, path):
        return path if os.path.isabs(path) else os.path.join(self._log_path, path)

    def _ensure_ttitracers_are_exist(self, sw_version):
        if self._is_folder_empty("TtiTracer") or self._is_file_not_exist():
            self._download_remote_file(sw_version, "TtiTracer.zip")
        if self._is_folder_empty("pscli"):
            self._download_remote_file(sw_version, "pstools.zip")

    def _is_file_not_exist(self):
        tool_name = "tti_trace_parser_wmp-linux.exe"
        try:
            self._executor.run('find {} -name {}'.format("/opt/TtiTracer", tool_name)).split()[0]
            is_exist = False
        except Exception:
            is_exist = True
        return is_exist

    def _is_folder_empty(self, folder_name):
        try:
            out, err, rc = self._executor.execute_command_and_return_all_result("ls -A /opt/TtiTracer/{}/ |wc -w".format(folder_name))
            is_empty = True if "No such file or directory" in err else False
        except Exception:
            is_empty = True
        return is_empty

    def _download_remote_file(self, sw_version, file_name):
        sw_version = (re.sub(r'SBTS[0-9A-Z]*_', "SBTS00_", sw_version)) if "9999" in sw_version else sw_version
        branch = sw_version.split("_")[0]
        wfturl = 'https://artifactory-espoo2.int.net.nokia.com/artifactory/mn-cosi-sran-central-public-local/build'
        link = "{}/{}/{}/{}_{}".format(wfturl, branch, sw_version, sw_version, file_name)
        if self._is_remote_file_exists(link):
            self._executor.execute_command('wget -P /opt/TtiTracer/ {} --timeout 10 --tries 1 --quiet'.format(link))
            self._executor.execute_command('unzip -qo /opt/TtiTracer/{}_{} -d /opt/TtiTracer/'.format(sw_version, file_name))
            self._executor.execute_command("rm /opt/TtiTracer/{}_{}".format(sw_version, file_name))
        else:
            logging.debug("Download {} fail. This file doesn't exist.".format(file_name))

    def _is_remote_file_exists(self, file_link):
        try:
            self._executor.execute_command("wget --spider {}".format(file_link))
            return True
        except Exception:
            return False

    def _ensure_ttitracers_are_executable(self):
        self._executor.run('sudo chmod u+x {}'.format(self._stream_path))
        self._executor.run('sudo chmod u+x {}'.format(self._tracer_path))

    def stop_server(self):
        """Kill FDD AirScale server process"""
        if self._is_server_model:
            add_port = "" if 'TTITraceServer.linux' in self._stream_path['server'] else '|grep {}'.format(self._port)
            cmd = "timeout 3 sudo kill -9 $(ps -ef|grep " + self._stream_path['server'] + add_port +\
                  "|grep -v grep|awk '{print $2}') 1>/dev/null 2>&1"
            self._executor.execute_command("{}\n".format(cmd.strip()))
            self._server_started = False

    def collect_logs(self):
        """collect logs from remote host to local PC"""
        self._executor.get_logs(self._log_files, self._log_path)

    def close_ssh_connection(self):
        """closes ssh connection in executor"""
        self._executor.close_connection()

    def _prepare_log_path(self):
        self._executor.run('[ ! -d "{log_path}" ] && mkdir -p "{log_path}" || true'.format(log_path=self._log_path))
        if not os.path.exists(self._log_path):
            os.makedirs(self._log_path)
